$(document).ready(function(){$('#regionsModal .js-region-search').on('keyup',function(){let phrase=$(this).val().trim().toLowerCase();let $list=$(this).siblings('.modal-regions-block').find('.row > div');if($list.length){$list.each(function(){$(this).show()});$list.each(function(){if($(this).find('a').html().trim().toLowerCase().indexOf(phrase)!==0){$(this).hide()}})}});$('#regionsModal .js-region-search-ajax').on('keyup',function(){let phrase=$(this).val().trim().toLowerCase();let $regions=$(this).siblings('.modal-regions-block').find('.row');if(phrase.length>=2){rxRunComponentAction('region.popup','search',{data:{post:{query:phrase}}}).then(function(res){$regions.html(res.data.html);$regions.css('display','flex')})}else{$regions.html('')}})});